// Chapter 4 cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch4).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['forms', ["Burning Peak, years ago", "Get up. Forms.", "Five more minutes, Minnow", "still drunk", "smoke on the road"]],
    ['the-offer', ["The Seal-House", "every key on these floors", "word for word", "very kind", "files it in the fire"]],
    ['the-heir', ["There she is", "have a mother", "whole Cult of them", "poison guests", "joking"]],
    ['the-sealed-archive', ["Inside, a girl", "VISITORS", "forbidden knowledge", "get you out", "for \"Gary\"", "gets a library"]],
    ['letters', ["mostly about Jin", "worst jokes", "remembers him", "reads them twice"]],
    ['the-key-under-the-floor', ["Under the floorboards", "dead or sober", "get to choose", "be anyone"]],
    ['jins-echo', ["Echo had stood", "Gu taught me a word", "out of order", "Up, Minnow. Forms.", "sounded like him"], [4]],
    ['a-choice-not-a-gift', ["No gift this time, love. A choice", "to open. You choose", "only her", "Not tonight"]],
    ['let-me-choose', ["seal scar", "One touch", "Let me choose.", "steps back", "Thank you."]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
